/**
 * Label rows by id across every workspace, so a caller can tell a label that
 * does not exist from one that belongs to another workspace. The caller must
 * check `orgId` on what comes back before using it.
 */
export async function findLabelsForReference(
  labelIds: readonly LabelId[],
): Promise<readonly IssueLabel[]> {
  if (labelIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(labels)
