/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side, narrowed to current members of the org.
 * Anyone else is dropped silently: not refused, and never notified.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
): Promise<readonly UserId[]> {
  const members = await memberRepo.listMembers({
    orgId,
    limit: MENTION_LOOKUP_LIMIT,
    cursor: null,
  });

  const resolved = resolveMentions(body, members.items);
  const candidates = [...new Set([...resolved, ...clientProvided])];
  const current = await memberRepo.findCurrentMemberUserIds(orgId, candidates);

  return candidates.filter((userId) => current.has(userId));
}

