import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issueLabels } from "@/server/db";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let a: Tenant;
let b: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  a = await createTenant("refa");
  b = await createTenant("refb");
});

afterAll(() => cleanup());

async function count(orgId: string) {
  return issueRepo.countIssues(orgId as never, a.project.id);
}

describe("reference checks", () => {
  it("refuses a label from another workspace and changes nothing", async () => {
    const bLabel = await labelRepo.insertLabel({ orgId: b.org.id, name: "bee", color: "#000000", description: null } as never);
    const before = await count(a.org.id);
    await expect(
      issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), labelIds: [bLabel.id] } as never),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await count(a.org.id)).toBe(before);
  });

  it("refuses an unknown label as not found on update", async () => {
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "lbl upd" }));
    await expect(
      issueService.updateIssue(a.actors.member, { orgId: a.org.id, issueId: issue.id, labelIds: ["lbl_nope"] } as never),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("never shows a foreign label attached to an issue", async () => {
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "leak check" }));
    const bLabel = await labelRepo.insertLabel({ orgId: b.org.id, name: "leaky", color: "#000000", description: null } as never);
    getDb().insert(issueLabels).values({ orgId: a.org.id, issueId: issue.id, labelId: bLabel.id }).run();
    const got = await issueService.getIssue(a.actors.member, a.org.id, issue.id);
    expect(got.labels).toEqual([]);
  });

  it("refuses a parent in another project of the same workspace", async () => {
    const other = await projectRepo.insertProject({
      orgId: a.org.id, name: "other proj", slug: "other", key: "OTH", description: null,
      visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
    });
    const parent = await issueService.createIssue(a.actors.member, issueInput(a.org.id, other.id, { title: "elsewhere" }));
    const before = await count(a.org.id);
    await expect(
      issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: parent.id } as never),
    ).rejects.toBeInstanceOf(NotFoundError);
    expect(await count(a.org.id)).toBe(before);
  });

  it("refuses an archived parent as not found", async () => {
    const parent = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "to archive" }));
    await issueService.archiveIssue(a.actors.owner, a.org.id, parent.id);
    await expect(
      issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: parent.id } as never),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a parent from another workspace as a tenant violation", async () => {
    const parent = await issueService.createIssue(b.actors.member, issueInput(b.org.id, b.project.id, { title: "b parent" }));
    await expect(
      issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), parentId: parent.id } as never),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("accepts a live parent in the same project", async () => {
    const parent = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "good parent" }));
    const child = await issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id, { title: "good child" }), parentId: parent.id } as never);
    expect(child.parentId).toBe(parent.id);
  });

  it("refuses an assignee who is not a current member, and assigns nothing", async () => {
    const outsider = await (await import("@/server/repositories/user-repository")).insertUser({
      email: "stranger@elsewhere.test", name: "stranger", passwordHash: "seed",
    });
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "assign check" }));
    const emitted: unknown[] = [];
    const off = subscribe("issue.assigned", (p) => { emitted.push(p); });
    try {
      await expect(
        issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: outsider.id }),
      ).rejects.toBeInstanceOf(NotFoundError);
      await expect(
        issueService.createIssue(a.actors.member, { ...issueInput(a.org.id, a.project.id), assigneeId: outsider.id } as never),
      ).rejects.toBeInstanceOf(NotFoundError);
    } finally {
      off();
    }
    expect(emitted).toHaveLength(0);
    const reread = await issueRepo.findIssueById(a.org.id, issue.id);
    expect(reread?.assigneeId).toBeNull();
  });

  it("refuses a removed member as assignee", async () => {
    const member = await memberRepo.findMember(a.org.id, a.userIds.viewer);
    await memberRepo.archiveMember(a.org.id, member!.id);
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "removed" }));
    await expect(
      issueService.assignIssue(a.actors.owner, { orgId: a.org.id, issueId: issue.id, assigneeId: a.userIds.viewer }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a project lead who is not a member, on create and update", async () => {
    const outsider = await (await import("@/server/repositories/user-repository")).insertUser({
      email: "lead@elsewhere.test", name: "lead", passwordHash: "seed",
    });
    const base = { orgId: a.org.id, name: "lead project", slug: "lead-proj", key: "LEAD", description: null, visibility: "org" as const, color: "#6366f1", targetDate: null };
    await expect(projectService.createProject(a.actors.owner, { ...base, leadId: outsider.id } as never)).rejects.toBeInstanceOf(NotFoundError);
    const ok = await projectService.createProject(a.actors.owner, { ...base, slug: "lead-ok", key: "LOK", leadId: a.userIds.admin } as never);
    await expect(projectService.updateProject(a.actors.owner, { orgId: a.org.id, projectId: ok.id, leadId: outsider.id } as never)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses a reply to a comment on another issue, a deleted one, or a reply", async () => {
    const issueA = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "thread A" }));
    const issueB = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "thread B" }));
    const onB = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: issueB.id, body: "on B", parentId: null, mentionedUserIds: [] });
    const top = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: issueA.id, body: "top", parentId: null, mentionedUserIds: [] });
    const reply = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: issueA.id, body: "reply", parentId: top.id, mentionedUserIds: [] });
    const gone = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: issueA.id, body: "gone", parentId: null, mentionedUserIds: [] });
    await commentService.deleteComment(a.actors.member, { orgId: a.org.id, commentId: gone.id });

    const base = { orgId: a.org.id, issueId: issueA.id, body: "x", mentionedUserIds: [] };
    await expect(commentService.createComment(a.actors.member, { ...base, parentId: onB.id } as never)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.createComment(a.actors.member, { ...base, parentId: gone.id } as never)).rejects.toBeInstanceOf(NotFoundError);
    await expect(commentService.createComment(a.actors.member, { ...base, parentId: reply.id } as never)).rejects.toBeInstanceOf(NotFoundError);

    const thread = await commentService.getThread(a.actors.member, a.org.id, issueA.id);
    expect(thread.flatMap((n) => n.replies)).toHaveLength(1);
  });

  it("refuses a reply target from another workspace as a tenant violation", async () => {
    const bIssue = await issueService.createIssue(b.actors.member, issueInput(b.org.id, b.project.id, { title: "b thread" }));
    const bComment = await commentService.createComment(b.actors.member, { orgId: b.org.id, issueId: bIssue.id, body: "b", parentId: null, mentionedUserIds: [] });
    const aIssue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "a thread" }));
    await expect(
      commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: aIssue.id, body: "x", parentId: bComment.id, mentionedUserIds: [] }),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("drops mentions of non-members from the stored list and the event", async () => {
    const outsider = await (await import("@/server/repositories/user-repository")).insertUser({
      email: "ghost@elsewhere.test", name: "ghost", passwordHash: "seed",
    });
    const issue = await issueService.createIssue(a.actors.member, issueInput(a.org.id, a.project.id, { title: "mentions" }));
    const seen: Array<readonly string[]> = [];
    const off = subscribe("comment.created", (p) => { seen.push(p.mentionedUserIds); });
    try {
      const c = await commentService.createComment(a.actors.member, {
        orgId: a.org.id, issueId: issue.id, body: "cc @admin",
