toolUseResult.originalFile:
/**
 * Checks on the things a write points at: an assignee, a project lead, a
 * parent issue, a reply target and labels. Each one must be usable from the
 * workspace the write is made in.
 *
 * A reference into another workspace is refused like any other cross-tenant
 * access (`TenantScopeError`). A reference that does not exist, is archived,
 * is not a current member, or sits in the wrong place is refused as not found
 * (`NotFoundError`). Every check runs before the write it guards, so a refused
 * change writes nothing and announces nothing.
 */
import { isLive } from "@/lib/soft-delete";
import { assertRowsInScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError, requireFound } from "./_support";
import type { CommentId, IssueId, LabelId, OrgId, ProjectId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

/** The user must be a current member of the workspace. */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const current = await memberRepo.findCurrentMemberUserIds(orgId, [userId]);
  if (!current.has(userId)) {
    throw new NotFoundError("Member", userId);
  }
}

/** The parent must be a live issue of the same project. */
export async function requireParentIssue(
  actor: Actor,
  parentId: IssueId,
  projectId: ProjectId,
): Promise<void> {
  const parent = requireFound(
    await issueRepo.findIssueForReference(parentId),
    "Issue",
    parentId,
  );
  assertRowsInScope(actor, [parent]);

  if (!isLive(parent) || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
}

/** The reply target must be a live, top-level comment on the same issue. */
export async function requireReplyTarget(
  actor: Actor,
  parentId: CommentId,
  issueId: IssueId,
): Promise<void> {
  const parent = requireFound(
    await commentRepo.findCommentForReference(parentId),
    "Comment",
    parentId,
  );
  assertRowsInScope(actor, [parent]);

  if (!isLive(parent) || parent.issueId !== issueId || parent.parentId !== null) {
    throw new NotFoundError("Comment", parentId);
  }
}

/** Every label must be one of the actor's workspace's own labels. */
export async function requireWorkspaceLabels(
  actor: Actor,
  labelIds: readonly LabelId[],
): Promise<void> {
  if (labelIds.length === 0) return;

  const found = await labelRepo.findLabelsForReference(labelIds);
  const byId = new Map(found.map((label) => [label.id, label]));

  for (const labelId of new Set(labelIds)) {
    const label = requireFound(byId.get(labelId) ?? null, "Label", labelId);
    assertRowsInScope(actor, [label]);
  }
}
